INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Schulungen für Mitarbeiter nur für IT-Personal nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Mitarbeiter sind Ziel"}, {"text": "Ja", "correct": false, "because": "Breitere Sensibilisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Mitarbeiterschulungen?', 3, '[{"text": "Sensibilisierung für Risiken", "correct": true, "because": "Verhindert Sicherheitslücken"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Themen gehören zu Mitarbeiterschulungen?', 5, '[{"text": "Phishing-Erkennung", "correct": true, "because": "Schützt vor Betrug"}, {"text": "Passwortmanagement", "correct": true, "because": "Sichert Zugänge"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schulungen reduzieren Sicherheitsrisiken. b) Sie sind nur einmalig nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Regelmäßigkeit erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Mitarbeiterschulungen?', 4, '[{"text": "Phishing-Beispiele", "correct": false, "because": "Sensibilisiert Mitarbeiter"}, {"text": "Sicherheitsrichtlinien", "correct": false, "because": "Wichtig für Verhalten"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schulungen auch Phishing abdecken?', 2, '[{"text": "Ja", "correct": true, "because": "Häufiges Thema"}, {"text": "Nein", "correct": false, "because": "Teil der Sensibilisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Thema ist typisch für Schulungen?', 3, '[{"text": "Social Engineering", "correct": true, "because": "Schützt vor Manipulation"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Schulungsthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte verbessern die Sicherheit durch Schulungen?', 5, '[{"text": "Passwortrichtlinien", "correct": true, "because": "Stärkt Zugangsschutz"}, {"text": "Phishing-Simulation", "correct": true, "because": "Trainiert Erkennung"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Schulungen minimieren menschliche Fehler. b) Sie sind nur für neue Mitarbeiter. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle brauchen regelmäßige Schulungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Mitarbeiterschulungen?', 4, '[{"text": "Praktische Übungen", "correct": false, "because": "Vertiefen Wissen"}, {"text": "Aktuelle Bedrohungen", "correct": false, "because": "Relevanz sicherstellen"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Schulungen nur für Phishing wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Abdecken viele Risiken"}, {"text": "Ja", "correct": false, "because": "Breitere Themen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutzen Schulungen?', 4, '[{"text": "Simulationen", "correct": true, "because": "Trainiert Reaktionen"}, {"text": "Theoretische Vorträge", "correct": true, "because": "Vermitteln Wissen"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schulungen einmalig ausreichen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Regelmäßigkeit nötig"}, {"text": "Ja", "correct": false, "because": "Bedrohungen ändern sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Schulungen?', 3, '[{"text": "Praktische Relevanz", "correct": true, "because": "Effektives Lernen"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Schriftarten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schulungen schützen vor Phishing. b) Sie sind nur für IT-Abteilungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Mitarbeiter betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte sind in Schulungen essenziell?', 5, '[{"text": "Social Engineering", "correct": true, "because": "Verhindert Manipulation"}, {"text": "Passwortsicherheit", "correct": true, "because": "Schützt Zugänge"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Schulungen unwichtig?', 3, '[{"text": "Aktuelle Bedrohungen", "correct": false, "because": "Erhöht Relevanz"}, {"text": "Praktische Beispiele", "correct": false, "because": "Vertieft Verständnis"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verhindern Schulungen alle Sicherheitsvorfälle?', 3, '[{"text": "Nein", "correct": true, "because": "Reduzieren, nicht eliminieren"}, {"text": "Ja", "correct": false, "because": "Begrenzte Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schulungen regelmäßig sein sollten?', 2, '[{"text": "Ja", "correct": true, "because": "Bedrohungen entwickeln sich"}, {"text": "Nein", "correct": false, "because": "Einmalig nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für effektive Schulungen?', 4, '[{"text": "Phishing-Simulation", "correct": true, "because": "Trainiert praktisch"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
